def is_simple_power(x, n):
    """
    Returns True if x is a simple power of n (i.e., x = n**int(x)),
    otherwise False.
    """
    if x < 0:
        return False
    if x == 1:
        return True
    if x == 0:
        return False
    if x < n:
        return False
    return x == n ** int(x)
