def rounded_avg(n, m):
    if n > m:
        return -1
    if n == m:
        return str(n)
    total = 0
    for i in range(n, m + 1):
        total += i
    avg = total / (m - n + 1)
    rounded = int(avg)
    if rounded == int(avg) + 0.5:
        rounded = int(avg) + 1
    return bin(rounded).replace('0b', '')
```

